(() => {
  'use strict';

  const I18N = {
    ru: {
      workspace:'Исследовательское пространство', back:'Вернуться в платформу', sidebarIntro:'Источники, файлы и наблюдения в едином доказательном контуре.',
      skip:'Перейти к содержанию', brandHome:'Global Index Research — главная', navLabel:'Навигация Data Lab', sections:'Разделы', close:'Закрыть', loading:'Собирается каталог доказательной базы…', language:'Переключить язык',
      navOverview:'Обзор', navSources:'Источники', navFiles:'Файлы', navRepro:'Воспроизводимость', status:'Каталог связан с рабочей SQLite', manifest:'CSV-манифест'
    },
    en: {
      workspace:'Research workspace', back:'Return to platform', sidebarIntro:'Sources, files and observations in a single evidence environment.',
      skip:'Skip to content', brandHome:'Global Index Research home', navLabel:'Data Lab navigation', sections:'Sections', close:'Close', loading:'Preparing the evidence catalogue…', language:'Switch language',
      navOverview:'Overview', navSources:'Sources', navFiles:'Files', navRepro:'Reproducibility', status:'Catalog connected to the live SQLite database', manifest:'CSV manifest'
    }
  };
  const state = {
    lang: localStorage.getItem('gir-lang') || localStorage.getItem('lang') || 'ru',
    theme: localStorage.getItem('gir-theme') || localStorage.getItem('theme') || 'dark',
    tab: new URLSearchParams(location.search).get('tab') || 'overview',
    summary: null, schema: null, sources: [],
    sourceFilters: {q:'', role:'all', access:'all'},
    files: {q:'', source:'all', extension:'all', kind:'all', access:'all', page:1, payload:null, loading:false},
    explorer: {
      dataset: new URLSearchParams(location.search).get('dataset') || '',
      measure: new URLSearchParams(location.search).get('measure') || '',
      chart: new URLSearchParams(location.search).get('chart') || 'line',
      countries: new Set((new URLSearchParams(location.search).get('countries') || '').split(',').filter(Boolean)),
      yearFrom: new URLSearchParams(location.search).get('year_from') || '',
      yearTo: new URLSearchParams(location.search).get('year_to') || '',
      dims: {}, xMeasure:'', scatterX:'HTEI', scatterY:'GII', result:null, loading:false
    },
    lastFocus:null
  };
  if (!['ru','en'].includes(state.lang)) state.lang='ru';
  if (!['dark','light'].includes(state.theme)) state.theme='dark';
  document.documentElement.lang=state.lang;
  document.documentElement.dataset.theme=state.theme;

  const $=(q,root=document)=>root.querySelector(q);
  const $$=(q,root=document)=>[...root.querySelectorAll(q)];
  const t=(ru,en)=>state.lang==='ru'?ru:en;
  const esc=value=>String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
  const fmt=(value,digits=1)=>value===null||value===undefined||Number.isNaN(Number(value))?'—':new Intl.NumberFormat(state.lang==='ru'?'ru-RU':'en-US',{maximumFractionDigits:digits,minimumFractionDigits:0}).format(Number(value));
  const humanBytes=value=>{let n=Number(value||0),i=0;const u=['B','KB','MB','GB','TB'];while(n>=1024&&i<u.length-1){n/=1024;i++}return `${i?fmt(n,1):Math.round(n)} ${u[i]}`};
  const labelOf=(obj,prefix='label')=>obj?.[`${prefix}_${state.lang}`]||obj?.[`${prefix}_ru`]||obj?.[`${prefix}_en`]||obj?.value||'';
  const titleOf=obj=>obj?.[`title_${state.lang}`]||obj?.title_ru||obj?.title_en||obj?.source_name||'';
  const descOf=obj=>obj?.[`description_${state.lang}`]||obj?.description_ru||obj?.description_en||'';
  const flag=iso=>{const c=state.schema?.countries?.find(x=>x.iso3===iso);const code=(c?.iso2||'').toUpperCase();return /^[A-Z]{2}$/.test(code)?String.fromCodePoint(...[...code].map(x=>127397+x.charCodeAt(0))):''};
  const countryName=iso=>{const c=state.schema?.countries?.find(x=>x.iso3===iso);return c?(state.lang==='ru'?c.name_ru:c.name_en)||c.name_en||c.name_ru||iso:iso};
  const countryLabel=iso=>`${flag(iso)} ${countryName(iso)}`.trim();
  const chartColors=['var(--chart-1)','var(--chart-2)','var(--chart-3)','var(--chart-4)','var(--chart-5)','var(--chart-6)','var(--chart-7)','var(--chart-8)','var(--chart-9)','var(--chart-10)','var(--chart-11)','var(--chart-12)'];
  const icons={download:'<svg viewBox="0 0 24 24"><path d="M12 3v12m-4-4 4 4 4-4M5 20h14"/></svg>',arrow:'<svg viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></svg>',chart:'<svg viewBox="0 0 24 24"><path d="M4 19V9m5 10V5m6 14v-7m5 7V3"/></svg>',file:'<svg viewBox="0 0 24 24"><path d="M6 2h8l4 4v16H6zM14 2v5h5"/></svg>',eye:'<svg viewBox="0 0 24 24"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>',code:'<svg viewBox="0 0 24 24"><path d="m8 9-4 3 4 3m8-6 4 3-4 3m-2-9-4 12"/></svg>',copy:'<svg viewBox="0 0 24 24"><rect x="8" y="8" width="12" height="12"/><path d="M16 8V4H4v12h4"/></svg>',info:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/></svg>'};
  const icon=name=>icons[name]||'';

  async function api(url){const response=await fetch(url,{cache:'no-store'});const contentType=response.headers.get('content-type')||'';let body;try{body=contentType.includes('json')?await response.json():await response.text()}catch{body=null}if(!response.ok){const detail=body?.detail;const message=typeof detail==='object'?(state.lang==='ru'?detail.message_ru:detail.message_en)||detail.code:detail||response.statusText;const error=new Error(message||response.statusText);error.status=response.status;error.body=body;throw error}return body}
  function toast(message){const el=$('#dl-toast');if(!el)return;el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2600)}
  function setURL(){const p=new URLSearchParams();if(state.tab!=='overview')p.set('tab',state.tab);if(state.tab==='explorer'){const x=state.explorer;p.set('dataset',x.dataset);p.set('measure',x.measure);p.set('chart',x.chart);if(x.countries.size)p.set('countries',[...x.countries].join(','));if(x.yearFrom)p.set('year_from',x.yearFrom);if(x.yearTo)p.set('year_to',x.yearTo);Object.entries(x.dims).forEach(([k,v])=>{if(v&&v!=='all')p.set(k,v)})}history.replaceState(null,'',`${location.pathname}${p.toString()?`?${p}`:''}`)}
  function applyStaticI18n(){$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(I18N[state.lang][key])el.textContent=I18N[state.lang][key]});$$('[data-i18n-aria]').forEach(el=>{const key=el.dataset.i18nAria;if(I18N[state.lang][key])el.setAttribute('aria-label',I18N[state.lang][key])});$('#dl-lang').textContent=state.lang==='ru'?'EN':'RU';$('#dl-lang').setAttribute('aria-label',I18N[state.lang].language);const themeLabel=t('Переключить тему','Switch theme');$('#dl-theme').setAttribute('aria-label',themeLabel);$('#dl-theme').setAttribute('title',themeLabel);document.title=t('Данные и исследование · Global Index Research','Data & research · Global Index Research')}

  function hero(){const s=state.summary;return `<section class="dl-hero"><div class="dl-hero-grid"><div><p class="dl-kicker">GLOBAL INDEX RESEARCH · DATA LAB</p><h1>${t('Доказательная база — от файла до вывода','Evidence base — from source file to finding')}</h1><p class="dl-hero-lead">${t('Исследуйте исходные наблюдения, компоненты индексов, международные рейтинги и документы прямо в интерфейсе. Каждая публикация связана с источником, режимом распространения, контрольной суммой и методом преобразования.','Explore source observations, index components, international rankings and documents directly in the interface. Every publication is linked to its source, distribution status, checksum and transformation method.')}</p><div class="dl-hero-actions"><button class="dl-btn dl-btn-primary" data-go="explorer">${icon('chart')}${t('Построить исследование','Start exploring')}</button><button class="dl-btn" data-go="files">${icon('file')}${t('Открыть библиотеку файлов','Open file library')}</button><a class="dl-btn dl-btn-quiet" href="/api/data-catalog/manifest.csv">${icon('download')}${t('Скачать манифест','Download manifest')}</a></div><div class="dl-trustline"><span><i></i>${t('Контроль SHA-256','SHA-256 integrity')}</span><span><i></i>${t('Права проверяются для каждой дистрибуции','Rights checked per distribution')}</span><span><i></i>${t('Машиночитаемые метаданные','Machine-readable metadata')}</span></div></div><div class="dl-proof"><div class="dl-proof-row"><span>${t('Источники','Sources')}<small>${t('международные, национальные и корпоративные','international, national and corporate')}</small></span><strong>${fmt(s.source_count,0)}</strong></div><div class="dl-proof-row"><span>${t('Каталогизированные файлы','Catalogued distributions')}<small>PDF · CSV · XLSX · JSON</small></span><strong>${fmt(s.catalog_distributions,0)}</strong></div><div class="dl-proof-row"><span>${t('Артефакты воспроизводимости','Reproducibility artifacts')}<small>${t('выгрузки, recipes и manifests','exports, recipes and manifests')}</small></span><strong>${fmt(s.reproducibility_artifacts,0)}</strong></div><div class="dl-proof-row"><span>${t('Локальный объём','Local volume')}<small>${t('с контролем прав доступа','with rights-aware access')}</small></span><strong>${humanBytes(s.total_local_bytes)}</strong></div></div></div></section>`}
  function mobileTabs(){const items=[['overview',t('Обзор','Overview')],['explorer','Data Explorer'],['sources',t('Источники','Sources')],['files',t('Файлы','Files')],['repro',t('Воспроизводимость','Reproducibility')]];return `<div class="dl-mobile-tabs" aria-label="${t('Разделы Data Lab','Data Lab sections')}">${items.map(([id,l])=>`<button data-tab="${id}" aria-current="${state.tab===id?'page':'false'}">${esc(l)}</button>`).join('')}</div>`}
  function metric(label,value,note){return `<article class="dl-metric"><span>${esc(label)}</span><strong>${fmt(value,0)}</strong><small>${esc(note)}</small></article>`}
  function pipeline(n,title,text){return `<article><b>${n}</b><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`}
  function sourceCard(source){const restricted=!source.redistribution_allowed&&!source.downloadable_count;const years=source.year_min?`${source.year_min}${source.year_max&&source.year_max!==source.year_min?`–${source.year_max}`:''}`:'—';return `<button class="dl-source-card" data-source="${esc(source.source_id)}"><span class="dl-source-top"><span class="dl-source-code">${esc(source.source_id)}</span><span class="dl-access ${restricted?'restricted':''}"><i></i>${restricted?t('производные данные','derived data'):t('есть доступные файлы','files available')}</span></span><h3>${esc(source.source_name)}</h3><p class="dl-source-owner">${esc(source.owner||'')}</p><div class="dl-formats">${(source.formats||[]).slice(0,7).map(x=>`<span class="dl-format">${esc(x)}</span>`).join('')}</div><div class="dl-source-stats"><div class="dl-source-stat"><span>${t('Файлы','Files')}</span><strong>${fmt(source.distribution_count,0)}</strong></div><div class="dl-source-stat"><span>${t('Период','Period')}</span><strong>${years}</strong></div><div class="dl-source-stat"><span>${t('Страны','Countries')}</span><strong>${fmt(source.country_count,0)}</strong></div><div class="dl-source-stat"><span>${t('Наблюдения','Observations')}</span><strong>${fmt(source.observation_count,0)}</strong></div></div></button>`}
  function overview(){const s=state.summary;const rows=s.database_rows||{};const observations=rows.source_observations||0;const analytic=Object.entries(rows).filter(([k])=>!['countries','source_observations'].includes(k)).reduce((a,[,v])=>a+Number(v||0),0);const access=Object.fromEntries((s.access||[]).map(x=>[x.key,x.count]));const maxFormat=Math.max(1,...(s.formats||[]).map(x=>x.count));return `<section class="dl-panel" data-panel="overview" ${state.tab==='overview'?'':'hidden'}><div class="dl-section"><div class="dl-section-head"><div><p class="dl-kicker">${t('Единый исследовательский контур','One research environment')}</p><h2>${t('Не архив файлов, а связанная система доказательств','Not a file dump, but a connected evidence system')}</h2></div><p>${t('Каталог различает исходный snapshot, производную выгрузку, рецепт обработки и метаданные. Пользователь видит данные, метод и правовой режим как части одной публикации.','The catalog distinguishes source snapshots, derived exports, processing recipes and metadata. Data, method and rights status are presented as parts of one publication.')}</p></div><div class="dl-metric-grid">${metric(t('Исходные наблюдения','Source observations'),observations,t('до окончательного отбора и агрегирования','before final selection and aggregation'))}${metric(t('Аналитические записи','Analytical records'),analytic,t('оценки, компоненты, университеты и модели','scores, components, institutions and models'))}${metric(t('Доступно для скачивания','Downloadable'),access.downloadable||0,t('после проектной проверки прав','after project rights review'))}${metric(t('Raw ограничен или только метаданные','Restricted or metadata only'),(access.restricted||0)+(access.metadata_only||0),t('официальный URL и provenance сохраняются','official URL and provenance retained'))}</div></div><div class="dl-section"><div class="dl-section-head"><div><p class="dl-kicker">PROVENANCE</p><h2>${t('Как значение проходит через платформу','How a value travels through the platform')}</h2></div></div><div class="dl-pipeline">${pipeline('01',t('Официальный источник','Official source'),t('Международная организация, статистическая служба, рейтинг или корпоративная отчётность.','International organisation, statistical office, ranking or corporate disclosure.'))}${pipeline('02',t('Зафиксированный snapshot','Captured snapshot'),t('Файл, дата получения, официальный URL и SHA-256 фиксируют исходное состояние.','File, retrieval date, official URL and SHA-256 capture the source state.'))}${pipeline('03',t('Гармонизация','Harmonisation'),t('Единицы, годы, классификации и страны приводятся к проверяемой схеме.','Units, years, classifications and countries are mapped to an auditable schema.'))}${pipeline('04',t('Расчёт и диагностика','Calculation & diagnostics'),t('Нормирование, веса, интервалы, quality flags и вклад в итоговый индекс.','Normalisation, weights, intervals, quality flags and contribution to the final index.'))}${pipeline('05',t('Публикация','Publication'),t('График, таблица, CSV, методические метаданные и происхождение значения.','Chart, table, CSV, methodological metadata and value provenance.'))}</div></div><div class="dl-section"><div class="dl-section-head"><div><p class="dl-kicker">${t('Ключевые коллекции','Key collections')}</p><h2>${t('Источники, которые формируют платформу','Sources that power the platform')}</h2></div><button class="dl-btn" data-go="sources">${t('Открыть весь каталог','Open full catalog')}${icon('arrow')}</button></div><div class="dl-source-grid">${state.sources.slice(0,6).map(sourceCard).join('')}</div></div><div class="dl-section"><div class="dl-section-head"><div><p class="dl-kicker">${t('Форматы','Formats')}</p><h2>${t('Документы и данные остаются доступны в исходной форме','Documents and data remain available in their native form')}</h2></div><p>${t('PDF открываются во встроенном viewer, табличные файлы — с preview строк и столбцов, JSON — как структурированные данные. Ограниченный raw заменяется разрешённой производной выгрузкой и официальной ссылкой.','PDFs open in an embedded viewer, tabular files show row and column previews, and JSON is rendered as structured data. Restricted raw files are replaced by approved derived exports and official links.')}</p></div><div class="dl-format-overview">${(s.formats||[]).map((f,i)=>`<div class="dl-format-row"><span><b>${esc(String(f.key||'').toUpperCase())}</b>${fmt(f.count,0)} ${t('файлов','files')}</span><div><i style="width:${Math.max(2,f.count/maxFormat*100)}%;--bar:${chartColors[i%chartColors.length]}"></i></div><strong>${humanBytes(f.bytes)}</strong></div>`).join('')}</div></div></section>`}

  function dataset(){return state.schema.datasets.find(d=>d.id===state.explorer.dataset)||state.schema.datasets[0]}
  function initExplorer(force=false){const d=dataset();if(!d)return;if(force||!d.measures.some(m=>m.code===state.explorer.measure))state.explorer.measure=d.default.measure||d.measures[0].code;if(force||!state.explorer.countries.size)state.explorer.countries=new Set(String(d.default.countries||'').split(',').filter(Boolean));if(force){state.explorer.yearFrom=d.year_min||'';state.explorer.yearTo=d.year_max||'';state.explorer.dims={}}d.dimensions.forEach(dim=>{if(!state.explorer.dims[dim.code])state.explorer.dims[dim.code]=d.default[dim.code]||'all'});if(!state.explorer.xMeasure||!d.measures.some(m=>m.code===state.explorer.xMeasure))state.explorer.xMeasure=d.measures.find(m=>m.code!==state.explorer.measure)?.code||''}
  function explorer(){initExplorer(false);const d=dataset();return `<section class="dl-panel" data-panel="explorer" ${state.tab==='explorer'?'':'hidden'}><div class="dl-section-head"><div><p class="dl-kicker">DATA EXPLORER</p><h2>${t('Любой показатель — как график, таблица или выгрузка','Any indicator — as a chart, table or export')}</h2></div><p>${t('Выберите аналитический набор, показатель, страны и период. Состояние сохраняется в URL, а CSV получает те же фильтры.','Choose a dataset, measure, countries and period. State is saved in the URL, and CSV uses the same filters.')}</p></div><div class="dl-explorer-shell"><aside class="dl-explorer-controls">${explorerControls(d)}</aside><div class="dl-explorer-main" id="dl-explorer-main">${explorerResult()}</div></div></section>`}
  function explorerControls(d){const x=state.explorer;const types=[['line',t('Линия','Line')],['bar',t('Столбцы','Bars')],['scatter',t('Связь','Scatter')],['histogram',t('Распределение','Distribution')],['table',t('Таблица','Table')]];return `<div class="dl-control-group"><h3 class="dl-control-title">${t('Что исследовать','What to explore')}</h3><label class="dl-label">${t('Набор данных','Dataset')}<select class="dl-control" data-ex-dataset>${state.schema.datasets.map(v=>`<option value="${v.id}" ${v.id===d.id?'selected':''}>${esc(titleOf(v))} · ${fmt(v.row_count,0)}</option>`).join('')}</select></label><label class="dl-label">${t('Показатель','Measure')}<select class="dl-control" data-ex-measure>${d.measures.map(m=>`<option value="${m.code}" ${m.code===x.measure?'selected':''}>${esc(labelOf(m))}</option>`).join('')}</select></label><div class="dl-chart-types" role="group" aria-label="${t('Тип визуализации','Visualisation type')}">${types.map(([id,l])=>`<button type="button" data-ex-chart="${id}" aria-pressed="${x.chart===id}" title="${esc(l)}">${esc(l)}</button>`).join('')}</div></div>${x.chart==='scatter'?scatterControls(d):''}<div class="dl-control-group"><h3 class="dl-control-title">${t('Фильтры','Filters')}</h3>${d.dimensions.filter(dim=>!(x.chart==='scatter'&&d.id==='index_scores'&&dim.code==='index_code')).map(dimensionControl).join('')}<div class="dl-year-row"><label class="dl-label">${t('С года','From year')}<input class="dl-control" type="number" min="1900" max="2100" value="${esc(x.yearFrom)}" data-ex-year-from></label><label class="dl-label">${t('По год','To year')}<input class="dl-control" type="number" min="1900" max="2100" value="${esc(x.yearTo)}" data-ex-year-to></label></div></div><div class="dl-control-group"><h3 class="dl-control-title">${t('Страны','Countries')}</h3>${countryPicker()}<div class="dl-presets"><button class="dl-preset" data-preset="tech">${t('Технологические','Technology peers')}</button><button class="dl-preset" data-preset="brics">БРИКС</button><button class="dl-preset" data-preset="g20">G20</button><button class="dl-preset" data-clear-countries>${t('Все страны','All countries')}</button></div><div class="dl-country-chips">${[...x.countries].map(iso=>`<span class="dl-country-chip">${esc(countryLabel(iso))}<button type="button" data-remove-country="${iso}" aria-label="${t('Удалить страну','Remove country')}">×</button></span>`).join('')}</div></div><button class="dl-btn dl-btn-primary" style="width:100%" data-run-explorer>${icon('chart')}${t('Построить','Run analysis')}</button>`}
  function scatterControls(d){if(d.id==='index_scores'){const dim=d.dimensions.find(v=>v.code==='index_code');return `<div class="dl-control-group"><h3 class="dl-control-title">${t('Оси диаграммы','Scatter axes')}</h3><label class="dl-label">X · ${t('индекс','index')}<select class="dl-control" data-scatter-x>${(dim?.options||[]).map(o=>`<option value="${esc(o.value)}" ${o.value===state.explorer.scatterX?'selected':''}>${esc(labelOf(o))}</option>`).join('')}</select></label><label class="dl-label">Y · ${t('индекс','index')}<select class="dl-control" data-scatter-y>${(dim?.options||[]).map(o=>`<option value="${esc(o.value)}" ${o.value===state.explorer.scatterY?'selected':''}>${esc(labelOf(o))}</option>`).join('')}</select></label><p class="dl-note">${t('Для каждой страны используется последний общий год двух индексов.','The latest common year of the two indices is used for each country.')}</p></div>`}return `<div class="dl-control-group"><h3 class="dl-control-title">${t('Оси диаграммы','Scatter axes')}</h3><label class="dl-label">X<select class="dl-control" data-x-measure>${d.measures.filter(m=>m.code!==state.explorer.measure).map(m=>`<option value="${m.code}" ${m.code===state.explorer.xMeasure?'selected':''}>${esc(labelOf(m))}</option>`).join('')}</select></label><p class="dl-note">Y · ${esc(labelOf(d.measures.find(m=>m.code===state.explorer.measure)))}</p></div>`}
  function dimensionControl(dim){const v=state.explorer.dims[dim.code]||'all';return `<label class="dl-label">${esc(labelOf(dim))}<select class="dl-control" data-dim="${dim.code}"><option value="all">${t('Все значения','All values')}</option>${dim.options.map(o=>`<option value="${esc(o.value)}" ${o.value===v?'selected':''}>${esc(labelOf(o))} · ${fmt(o.count,0)}</option>`).join('')}</select></label>`}
  function countryPicker(){const n=state.explorer.countries.size;return `<div class="dl-country-picker"><button class="dl-btn dl-country-button" type="button" data-country-button aria-expanded="false"><span>${n?t(`Выбрано: ${n}`,`${n} selected`):t('Все доступные страны','All available countries')}</span><span>⌄</span></button><div class="dl-country-popover"><input class="dl-control" type="search" placeholder="${t('Поиск страны','Search country')}" data-country-search><div class="dl-country-list">${countryOptions('')}</div></div></div>`}
  function countryOptions(q){q=String(q||'').toLowerCase();return state.schema.countries.filter(c=>!q||[c.iso3,c.name_ru,c.name_en].some(v=>String(v||'').toLowerCase().includes(q))).map(c=>`<label class="dl-country-option"><input type="checkbox" value="${c.iso3}" data-country-check ${state.explorer.countries.has(c.iso3)?'checked':''}><span>${esc(`${flag(c.iso3)} ${state.lang==='ru'?c.name_ru:c.name_en}`.trim())}</span><span>${c.iso3}</span></label>`).join('')}
  function explorerResult(){const x=state.explorer,d=dataset();if(x.loading)return `<div class="dl-loading compact"><div><div class="dl-loading-mark">G</div><p>${t('Формируется аналитическая выборка…','Building analytical selection…')}</p></div></div>`;if(!x.result)return `<div class="dl-empty"><div><h2>${esc(titleOf(d))}</h2><p>${esc(descOf(d))}</p><button class="dl-btn dl-btn-primary" data-run-explorer>${t('Построить первое представление','Build the first view')}</button></div></div>`;if(x.result.error)return `<div class="dl-error">${esc(x.result.error)}</div>`;const r=x.result,query=explorerQuery(false),unit=(r.units||[]).join(', ')||t('единица не указана','unit not specified');return `<div class="dl-explorer-head"><div class="dl-explorer-head-top"><div><h2>${esc(titleOf(r.dataset_meta))}</h2><p>${esc(descOf(r.dataset_meta))}</p></div><div class="dl-hero-actions" style="margin:0"><a class="dl-btn" href="/api/data-explorer/export.csv?${query}">${icon('download')}CSV</a><a class="dl-btn dl-btn-quiet" href="/api/data-explorer/datasets/${encodeURIComponent(r.dataset)}/metadata.json" target="_blank">${icon('code')}Metadata</a></div></div><div class="dl-summary-strip">${summaryItem(t('Строк','Rows'),r.summary.returned_rows)}${summaryItem(t('Стран','Countries'),r.summary.country_count)}${summaryItem(t('Серий','Series'),r.summary.series_count)}${summaryItem(t('Период','Period'),r.summary.year_min?`${r.summary.year_min}–${r.summary.year_max}`:'—')}${summaryItem(t('Среднее','Mean'),fmt(r.summary.value_mean,2))}</div></div>${(state.lang==='ru'?r.warnings_ru:r.warnings_en).map(w=>`<div class="dl-warning">${esc(w)}</div>`).join('')}<div class="dl-visual"><div class="dl-visual-toolbar"><div class="dl-visual-title"><h3>${esc(chartTitle(r))}</h3><p>${esc(`${unit} · n = ${fmt(r.summary.returned_rows,0)}`)}</p></div><button class="dl-btn dl-btn-quiet" data-copy-link>${icon('copy')}${t('Скопировать ссылку','Copy link')}</button></div><div class="dl-chart-canvas" id="dl-chart">${renderChart(r)}</div><div class="dl-legend">${chartLegend(r)}</div></div><div class="dl-explorer-foot"><section class="dl-evidence"><h3>${t('Источники выборки','Sources in this selection')}</h3>${r.sources.length?r.sources.map(s=>`<div class="dl-source-line"><span><b>${esc(s.source_id)}</b><br>${esc(s.owner||s.source_name||'')}</span>${/^https?:/.test(s.source_url||'')?`<a href="${esc(s.source_url)}" target="_blank" rel="noopener">${t('Официальный источник','Official source')} ↗</a>`:''}</div>`).join(''):`<p class="dl-meta">${t('Источник указан на уровне строки таблицы.','The source is recorded at row level.')}</p>`}</section><section class="dl-metadata"><h3>${t('Метаданные исследования','Research metadata')}</h3><div class="dl-detail-list"><div class="dl-detail-row"><span>${t('Набор','Dataset')}</span><strong>${esc(r.dataset)}</strong></div><div class="dl-detail-row"><span>${t('Показатель','Measure')}</span><strong>${esc(labelOf(r.measure_meta))}</strong></div><div class="dl-detail-row"><span>${t('Полная выборка','Full selection')}</span><strong>${fmt(r.summary.total_rows,0)}</strong></div><div class="dl-detail-row"><span>${t('Схема','Schema')}</span><strong><a href="/api/data-explorer/datasets/${encodeURIComponent(r.dataset)}/metadata.json" target="_blank">CSVW JSON</a></strong></div></div></section></div>${resultTable(r)}`}
  function summaryItem(l,v){return `<div class="dl-summary-item"><span>${esc(l)}</span><strong>${typeof v==='number'?fmt(v,0):esc(v)}</strong></div>`}
  function chartTitle(r){const m=labelOf(r.measure_meta);if(state.explorer.chart==='scatter'&&r.dataset==='index_scores')return `${state.explorer.scatterY} ${t('относительно','against')} ${state.explorer.scatterX}`;if(state.explorer.chart==='scatter')return `${m} · ${t('взаимосвязь','relationship')}`;if(state.explorer.chart==='histogram')return `${m} · ${t('распределение','distribution')}`;if(state.explorer.chart==='line')return `${m} · ${t('динамика','trend')}`;if(state.explorer.chart==='bar')return `${m} · ${t('сопоставление','comparison')}`;return `${m} · ${t('таблица','table')}`}
  function resultTable(r){const rows=r.rows.slice(0,250);return `<section class="dl-table-card"><div class="dl-table-head"><div><h3>${t('Таблица наблюдений','Observation table')}</h3><span class="dl-meta">${t(`Показано ${rows.length} из ${r.summary.total_rows}`,`Showing ${rows.length} of ${r.summary.total_rows}`)}</span></div><a class="dl-btn" href="/api/data-explorer/export.csv?${explorerQuery(false)}">${icon('download')}${t('Полная CSV','Full CSV')}</a></div><div class="dl-table-scroll"><table class="dl-table"><thead><tr><th>${t('Страна','Country')}</th><th>${t('Год','Year')}</th><th>${t('Серия','Series')}</th><th>${t('Значение','Value')}</th><th>${t('Единица','Unit')}</th><th>${t('Источник','Source')}</th><th>${t('Доказательство','Evidence')}</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(`${flag(row.iso3)} ${state.lang==='ru'?row.country_ru:row.country_en}`.trim())}<br><small>${esc(row.iso3||'')}</small></td><td>${esc(row.year??'—')}</td><td>${esc(state.lang==='ru'?row.series_ru:row.series_en)}<br><small>${esc(row.series_code||'')}</small></td><td><strong>${fmt(row.value,3)}</strong>${row.x_value!=null?`<br><small>X: ${fmt(row.x_value,3)}</small>`:''}</td><td>${esc(row.unit||'—')}</td><td>${esc(row.source_id||'—')}</td><td>${row.value_id?`<button class="dl-provenance-button" data-provenance="${esc(row.value_id)}" aria-label="${t('Открыть происхождение значения','Open value provenance')}">${icon('info')}</button>`:'—'}</td></tr>`).join('')}</tbody></table></div></section>`}

  function chartGroups(rows){const map=new Map();rows.forEach(row=>{const key=`${row.iso3||''}|${row.series_code||''}`;if(!map.has(key))map.set(key,{key,label:[row.iso3?countryLabel(row.iso3):'',state.lang==='ru'?row.series_ru:row.series_en].filter(Boolean).join(' · '),rows:[]});map.get(key).rows.push(row)});return [...map.values()]}
  function chartLegend(r){if(['histogram','table'].includes(state.explorer.chart))return'';return chartGroups(r.rows).slice(0,12).map((g,i)=>`<span class="dl-legend-item"><i style="--legend:${chartColors[i%chartColors.length]}"></i>${esc(g.label)}</span>`).join('')}
  const extent=values=>{const v=values.map(Number).filter(Number.isFinite);if(!v.length)return[0,1];let a=Math.min(...v),b=Math.max(...v);if(a===b){const p=Math.abs(a||1)*.1;a-=p;b+=p}return[a,b]};
  const scale=(d0,d1,r0,r1)=>v=>r0+(Number(v)-d0)/(d1-d0||1)*(r1-r0);
  const ticks=(a,b,n=5)=>Array.from({length:n+1},(_,i)=>a+(b-a)*i/n);
  function axes(W,H,m,xt,yt,xs,ys,xf=v=>fmt(v,0),yf=v=>fmt(v,1)){let out='';yt.forEach(v=>{const y=ys(v);out+=`<line class="dl-chart-grid" x1="${m.left}" x2="${W-m.right}" y1="${y}" y2="${y}"/><text class="dl-chart-text" x="${m.left-9}" y="${y+3}" text-anchor="end">${esc(yf(v))}</text>`});xt.forEach(v=>{const x=xs(v);out+=`<line class="dl-chart-grid" y1="${m.top}" y2="${H-m.bottom}" x1="${x}" x2="${x}"/><text class="dl-chart-text" x="${x}" y="${H-m.bottom+20}" text-anchor="middle">${esc(xf(v))}</text>`});return out+`<line class="dl-chart-axis" x1="${m.left}" x2="${W-m.right}" y1="${H-m.bottom}" y2="${H-m.bottom}"/><line class="dl-chart-axis" x1="${m.left}" x2="${m.left}" y1="${m.top}" y2="${H-m.bottom}"/>`}
  function tip(value){return `data-tip="${esc(value).replace(/\n/g,'&#10;')}" tabindex="0"`}
  function renderChart(r){if(!r.rows.length)return `<div class="dl-chart-message"><div><strong>${t('Нет наблюдений для выбранных фильтров','No observations match the selected filters')}</strong><br>${t('Измените страны, период или методический режим.','Change countries, period or methodological mode.')}</div></div>`;if(state.explorer.chart==='table')return `<div class="dl-chart-message"><div>${t('Точное представление находится в таблице ниже.','The exact view is available in the table below.')}</div></div>`;if(state.explorer.chart==='bar')return bars(r);if(state.explorer.chart==='histogram')return histogram(r);if(state.explorer.chart==='scatter')return scatter(r);return lines(r)}
  function lines(r){const groups=chartGroups(r.rows).filter(g=>g.rows.some(x=>x.year!=null)).slice(0,12),years=[...new Set(groups.flatMap(g=>g.rows.map(x=>Number(x.year)).filter(Number.isFinite)))].sort((a,b)=>a-b);if(years.length<2)return `<div class="dl-chart-message"><div><strong>${t('Для временной линии недостаточно точек','Not enough points for a trend line')}</strong><br>${t('Выберите столбцы или таблицу.','Choose bars or table.')}</div></div>`;const values=groups.flatMap(g=>g.rows.map(x=>x.value)),[y0,y1]=extent(values),pad=(y1-y0)*.08,W=960,H=430,m={left:66,right:28,top:22,bottom:48},xs=scale(years[0],years.at(-1),m.left,W-m.right),ys=scale(y0-pad,y1+pad,H-m.bottom,m.top),xt=years.length<=8?years:years.filter((_,i)=>i%Math.ceil(years.length/7)===0||i===years.length-1);let svg=axes(W,H,m,xt,ticks(y0-pad,y1+pad,5),xs,ys,v=>Math.round(v),v=>fmt(v,1));groups.forEach((g,i)=>{const rows=[...g.rows].filter(x=>x.year!=null&&x.value!=null).sort((a,b)=>a.year-b.year),d=rows.map((p,j)=>`${j?'L':'M'}${xs(p.year).toFixed(1)},${ys(p.value).toFixed(1)}`).join(' ');svg+=`<path class="dl-chart-line" stroke="${chartColors[i%chartColors.length]}" d="${d}"/>`;rows.forEach(p=>svg+=`<circle class="dl-chart-point" fill="${chartColors[i%chartColors.length]}" cx="${xs(p.year)}" cy="${ys(p.value)}" r="4" ${tip(`${g.label}\n${p.year}: ${fmt(p.value,3)} ${p.unit||''}`)}/>`)});return `<svg viewBox="0 0 ${W} ${H}" role="img"><title>${esc(chartTitle(r))}</title><desc>${t('Линейный график по годам для выбранных стран и серий.','Line chart by year for selected countries and series.')}</desc>${svg}</svg>`}
  function latest(rows){const map=new Map();rows.forEach(r=>{const k=`${r.iso3||''}|${r.series_code||''}`;const p=map.get(k);if(!p||Number(r.year||0)>Number(p.year||0))map.set(k,r)});return[...map.values()]}
  function bars(r){let rows=latest(r.rows).filter(x=>x.value!=null);const lower=/rank|место/i.test(state.explorer.measure);rows.sort((a,b)=>lower?a.value-b.value:b.value-a.value);rows=rows.slice(0,20);const vals=rows.map(x=>x.value);let[min,max]=extent(vals);min=Math.min(0,min);max=Math.max(0,max);const W=960,H=Math.max(410,rows.length*31+75),m={left:250,right:75,top:20,bottom:42},xs=scale(min,max,m.left,W-m.right),zero=xs(0),rh=(H-m.top-m.bottom)/rows.length;let svg='';ticks(min,max,5).forEach(v=>{const x=xs(v);svg+=`<line class="dl-chart-grid" y1="${m.top}" y2="${H-m.bottom}" x1="${x}" x2="${x}"/><text class="dl-chart-text" x="${x}" y="${H-m.bottom+20}" text-anchor="middle">${fmt(v,1)}</text>`});rows.forEach((row,i)=>{const y=m.top+i*rh+rh*.15,h=rh*.7,x=xs(Math.min(0,row.value)),w=Math.abs(xs(row.value)-zero),label=[row.iso3?countryLabel(row.iso3):'',state.lang==='ru'?row.series_ru:row.series_en].filter(Boolean).join(' · ');svg+=`<text class="dl-chart-text" x="${m.left-10}" y="${y+h*.68}" text-anchor="end">${esc(label.length>39?label.slice(0,38)+'…':label)}</text><rect x="${x}" y="${y}" width="${Math.max(1,w)}" height="${h}" fill="${chartColors[i%chartColors.length]}" ${tip(`${label}\n${row.year||''}: ${fmt(row.value,3)} ${row.unit||''}`)}/><text class="dl-chart-value" x="${row.value>=0?x+w+6:x-6}" y="${y+h*.68}" text-anchor="${row.value>=0?'start':'end'}">${fmt(row.value,2)}</text>`});return `<svg viewBox="0 0 ${W} ${H}" role="img"><title>${esc(chartTitle(r))}</title><desc>${t('Столбчатая диаграмма последних доступных значений.','Bar chart of latest available values.')}</desc>${svg}</svg>`}
  function histogram(r){const values=r.rows.map(x=>Number(x.value)).filter(Number.isFinite);if(values.length<8)return `<div class="dl-chart-message"><div><strong>${t('Для распределения требуется минимум восемь наблюдений','At least eight observations are required')}</strong><br>${t('Расширьте выборку.','Broaden the selection.')}</div></div>`;const[min,max]=extent(values),n=Math.min(16,Math.max(8,Math.round(Math.sqrt(values.length)))),step=(max-min)/n||1,bins=Array.from({length:n},(_,i)=>({a:min+i*step,b:i===n-1?max:min+(i+1)*step,n:0}));values.forEach(v=>bins[Math.min(n-1,Math.floor((v-min)/step))].n++);const W=960,H=430,m={left:58,right:25,top:22,bottom:52},xs=scale(min,max,m.left,W-m.right),ys=scale(0,Math.max(...bins.map(b=>b.n)),H-m.bottom,m.top);let svg=axes(W,H,m,ticks(min,max,6),ticks(0,Math.max(...bins.map(b=>b.n)),5),xs,ys,v=>fmt(v,1),v=>fmt(v,0));bins.forEach(b=>{const x=xs(b.a)+2,w=Math.max(1,xs(b.b)-xs(b.a)-4),y=ys(b.n);svg+=`<rect x="${x}" y="${y}" width="${w}" height="${H-m.bottom-y}" fill="${chartColors[0]}" ${tip(`${fmt(b.a,2)}–${fmt(b.b,2)}\nn = ${b.n}`)}/>`});return `<svg viewBox="0 0 ${W} ${H}" role="img"><title>${esc(chartTitle(r))}</title><desc>${t('Гистограмма распределения выбранных значений.','Histogram of selected values.')}</desc>${svg}</svg>`}
  function scatterPoints(r){if(r.dataset==='index_scores'){const by=new Map();r.rows.forEach(row=>{const k=`${row.iso3}|${row.year}`;if(!by.has(k))by.set(k,{});by.get(k)[row.series_code]=row});const latestMap=new Map();for(const[k,pair]of by){if(!pair[state.explorer.scatterX]||!pair[state.explorer.scatterY])continue;const[iso,year]=k.split('|'),prev=latestMap.get(iso);if(!prev||Number(year)>prev.year)latestMap.set(iso,{iso3:iso,year:Number(year),x:pair[state.explorer.scatterX].value,y:pair[state.explorer.scatterY].value,label:state.lang==='ru'?pair[state.explorer.scatterX].country_ru:pair[state.explorer.scatterX].country_en,region:pair[state.explorer.scatterX].region})}return[...latestMap.values()]}return r.rows.filter(x=>x.x_value!=null&&x.value!=null).map(x=>({iso3:x.iso3,year:x.year,x:x.x_value,y:x.value,label:state.lang==='ru'?x.country_ru:x.country_en,region:x.region}))}
  function scatter(r){const points=scatterPoints(r);if(points.length<8)return `<div class="dl-chart-message"><div><strong>${t('Недостаточно сопоставимых наблюдений','Not enough comparable observations')}</strong><br>${t('Нужно не менее восьми точек. Расширьте выборку.','At least eight points are required. Broaden the selection.')}</div></div>`;const[x0,x1]=extent(points.map(p=>p.x)),[y0,y1]=extent(points.map(p=>p.y)),px=(x1-x0)*.08,py=(y1-y0)*.08,W=960,H=460,m={left:66,right:35,top:24,bottom:66},xs=scale(x0-px,x1+px,m.left,W-m.right),ys=scale(y0-py,y1+py,H-m.bottom,m.top),regions=[...new Set(points.map(p=>p.region||'—'))];let svg=axes(W,H,m,ticks(x0-px,x1+px,5),ticks(y0-py,y1+py,5),xs,ys,v=>fmt(v,1),v=>fmt(v,1));points.forEach(p=>{const i=Math.max(0,regions.indexOf(p.region||'—')),r0=p.iso3==='RUS'?7:5;svg+=`<circle class="dl-chart-point" cx="${xs(p.x)}" cy="${ys(p.y)}" r="${r0}" fill="${chartColors[i%chartColors.length]}" ${tip(`${p.label} (${p.iso3})\nX: ${fmt(p.x,2)}\nY: ${fmt(p.y,2)}\n${p.year||''}`)}/>`;if(points.length<=30||p.iso3==='RUS')svg+=`<text class="dl-chart-value" x="${xs(p.x)+7}" y="${ys(p.y)-7}">${esc(p.iso3)}</text>`});return `<svg viewBox="0 0 ${W} ${H}" role="img"><title>${esc(chartTitle(r))}</title><desc>${t('Диаграмма рассеяния сопоставимых наблюдений; цвет обозначает регион.','Scatter plot of comparable observations; colour denotes region.')}</desc>${svg}</svg>`}
  function explorerQuery(withLimit=true){const x=state.explorer,p=new URLSearchParams({dataset:x.dataset,measure:x.measure});if(x.countries.size)p.set('countries',[...x.countries].join(','));if(x.yearFrom)p.set('year_from',x.yearFrom);if(x.yearTo)p.set('year_to',x.yearTo);Object.entries(x.dims).forEach(([k,v])=>{if(v&&v!=='all')p.set(k,v)});if(x.chart==='scatter'&&x.dataset==='index_scores')p.set('index_code',`${x.scatterX},${x.scatterY}`);else if(x.chart==='scatter'&&x.xMeasure)p.set('x_measure',x.xMeasure);if(withLimit)p.set('limit','5000');return p.toString()}
  async function runExplorer(){state.explorer.loading=true;renderExplorerResult();setURL();try{state.explorer.result=await api(`/api/data-explorer/query?${explorerQuery(true)}`)}catch(e){state.explorer.result={error:e.message}}state.explorer.loading=false;renderExplorerResult();setURL()}
  function renderExplorerResult(){const el=$('#dl-explorer-main');if(el){el.innerHTML=explorerResult();bindExplorerResult()}}

  function sourcesPanel(){const roles=[...new Set(state.sources.map(s=>s.source_role).filter(Boolean))].sort();return `<section class="dl-panel" data-panel="sources" ${state.tab==='sources'?'':'hidden'}><div class="dl-section-head"><div><p class="dl-kicker">SOURCE CATALOG</p><h2>${t('Кто произвёл данные и как они используются','Who produced the data and how it is used')}</h2></div><p>${t('Карточка источника объединяет организацию, временной охват, роль в индексах, лицензионную оценку и связанные дистрибуции.','Each source record combines the publisher, temporal coverage, role in indices, licence review and related distributions.')}</p></div><div class="dl-toolbar"><input class="dl-control" type="search" data-source-q aria-label="${t('Поиск по источникам','Search sources')}" placeholder="${t('Источник, организация или индекс…','Source, organisation or index…')}"><select class="dl-control" data-source-role aria-label="${t('Фильтр по роли источника','Filter by source role')}"><option value="all">${t('Все роли','All roles')}</option>${roles.map(r=>`<option value="${esc(r)}">${esc(r.replaceAll('_',' '))}</option>`).join('')}</select><select class="dl-control" data-source-access aria-label="${t('Фильтр по режиму доступа','Filter by access status')}"><option value="all">${t('Любой доступ','Any access')}</option><option value="downloadable">${t('Есть доступные файлы','Files available')}</option><option value="restricted">${t('Только производные данные','Derived only')}</option></select></div><p class="dl-results-meta" id="dl-source-count"></p><div class="dl-source-grid" id="dl-source-grid"></div></section>`}
  function filteredSources(){const f=state.sourceFilters,q=f.q.toLowerCase();return state.sources.filter(s=>(!q||[s.source_id,s.source_name,s.owner,s.title,(s.related_indices||[]).join(' ')].join(' ').toLowerCase().includes(q))&&(f.role==='all'||s.source_role===f.role)&&(f.access==='all'||(f.access==='downloadable'?(s.redistribution_allowed||s.downloadable_count):(!s.redistribution_allowed&&!s.downloadable_count))))}
  function renderSources(){const grid=$('#dl-source-grid');if(!grid)return;const items=filteredSources();$('#dl-source-count').textContent=t(`Показано источников: ${items.length}`,`Sources shown: ${items.length}`);grid.innerHTML=items.length?items.map(sourceCard).join(''):`<div class="dl-empty"><div>${t('Источники по выбранным фильтрам не найдены.','No sources match the selected filters.')}</div></div>`;$$('[data-source]',grid).forEach(el=>el.addEventListener('click',()=>openSource(el.dataset.source,el)))}
  function filesPanel(){const exts=(state.summary.formats||[]).map(x=>x.key),kinds=(state.summary.distribution_kinds||[]).map(x=>x.key);return `<section class="dl-panel" data-panel="files" ${state.tab==='files'?'':'hidden'}><div class="dl-section-head"><div><p class="dl-kicker">FILE LIBRARY</p><h2>${t('Все документы и выгрузки — с понятным режимом доступа','Every document and export — with a clear access status')}</h2></div><p>${t('Библиотека показывает не только имя файла, но и его роль: raw snapshot, извлечённая таблица, производная выгрузка, рецепт или manifest.','The library shows not only a filename, but its role: raw snapshot, extracted table, derived export, recipe or manifest.')}</p></div><div class="dl-file-summary">${(state.summary.formats||[]).slice(0,4).map(f=>`<div><span>${esc(String(f.key).toUpperCase())}</span><strong>${fmt(f.count,0)}</strong></div>`).join('')}</div><div class="dl-toolbar"><input class="dl-control" type="search" data-file-q aria-label="${t('Поиск по файлам','Search files')}" placeholder="${t('Имя файла, источник или идентификатор…','Filename, source or identifier…')}"><select class="dl-control" data-file-source aria-label="${t('Фильтр файлов по источнику','Filter files by source')}"><option value="all">${t('Все источники','All sources')}</option>${state.sources.map(s=>`<option value="${esc(s.source_id)}">${esc(s.source_id)}</option>`).join('')}</select><select class="dl-control" data-file-ext aria-label="${t('Фильтр файлов по формату','Filter files by format')}"><option value="all">${t('Все форматы','All formats')}</option>${exts.map(x=>`<option value="${esc(x)}">${esc(String(x).toUpperCase())}</option>`).join('')}</select><select class="dl-control" data-file-access aria-label="${t('Фильтр файлов по доступу','Filter files by access')}"><option value="all">${t('Любой доступ','Any access')}</option><option value="downloadable">${t('Можно скачать','Downloadable')}</option><option value="restricted">${t('Raw ограничен','Raw restricted')}</option><option value="metadata_only">${t('Только метаданные','Metadata only')}</option></select></div><div class="dl-file-list" id="dl-file-list"><div class="dl-loading compact"><div><div class="dl-loading-mark">G</div></div></div></div></section>`}
  async function loadFiles(){const f=state.files;f.loading=true;renderFiles();const p=new URLSearchParams({page:String(f.page),page_size:'30'});if(f.q)p.set('q',f.q);if(f.source!=='all')p.set('source_id',f.source);if(f.extension!=='all')p.set('extension',f.extension);if(f.kind!=='all')p.set('kind',f.kind);if(f.access!=='all')p.set('access',f.access);try{f.payload=await api(`/api/data-catalog/files?${p}`)}catch(e){f.payload={error:e.message,files:[],total:0,pages:1,page:1}}f.loading=false;renderFiles()}
  function renderFiles(){const el=$('#dl-file-list');if(!el)return;const f=state.files;if(f.loading){el.innerHTML='<div class="dl-loading compact"><div><div class="dl-loading-mark">G</div></div></div>';return}if(!f.payload){loadFiles();return}if(f.payload.error){el.innerHTML=`<div class="dl-error">${esc(f.payload.error)}</div>`;return}const p=f.payload;el.innerHTML=p.files.length?p.files.map(fileRow).join('')+`<div class="dl-pagination"><span>${t(`Страница ${p.page} из ${p.pages} · ${p.total} файлов`,`Page ${p.page} of ${p.pages} · ${p.total} files`)}</span><div class="dl-page-actions"><button class="dl-btn" data-file-prev ${p.page<=1?'disabled':''}>← ${t('Назад','Previous')}</button><button class="dl-btn" data-file-next ${p.page>=p.pages?'disabled':''}>${t('Далее','Next')} →</button></div></div>`:`<div class="dl-empty"><div>${t('Файлы по выбранным условиям не найдены.','No files match the selected filters.')}</div></div>`;$$('[data-file-open]',el).forEach(b=>b.addEventListener('click',()=>openFile(b.dataset.fileOpen,b)));$('[data-file-prev]',el)?.addEventListener('click',()=>{f.page--;loadFiles()});$('[data-file-next]',el)?.addEventListener('click',()=>{f.page++;loadFiles()})}
  function fileRow(file){const status=file.download_allowed?['',t('можно скачать','downloadable')]:file.exists_locally?['restricted',t('raw ограничен','raw restricted')]:['metadata',t('только метаданные','metadata only')];return `<div class="dl-file-row"><div class="dl-file-main"><span class="dl-file-icon">${esc(file.extension||'file')}</span><span class="dl-file-name"><strong>${esc(state.lang==='ru'?file.title_ru:file.title_en)}</strong><span>${esc(file.filename)}</span></span></div><div class="dl-file-cell"><strong>${esc(file.source_id||'—')}</strong>${esc(file.distribution_kind||'')}</div><div class="dl-file-cell"><strong>${esc(file.release_year||'—')}</strong>${esc(file.bytes_human||'')}</div><div class="dl-file-cell"><span class="dl-status-pill ${status[0]}">${status[1]}</span></div><div class="dl-file-cell"><strong>SHA-256</strong>${esc((file.sha256||'').slice(0,10))}…</div><button class="dl-file-action" data-file-open="${esc(file.file_id)}" aria-label="${t('Открыть файл','Open file')}">${icon('eye')}</button></div>`}
  function reproPanel(){const s=state.summary;return `<section class="dl-panel" data-panel="repro" ${state.tab==='repro'?'':'hidden'}><div class="dl-section-head"><div><p class="dl-kicker">REPRODUCIBILITY</p><h2>${t('Машиночитаемый каталог и проверяемая цепочка публикации','Machine-readable catalog and auditable publication chain')}</h2></div><p>${t('Публичный интерфейс дополняется DCAT JSON-LD, схемами аналитических таблиц, CSV-манифестом файлов и SHA-256 для контроля целостности.','The public interface is backed by DCAT JSON-LD, analytical table schemas, a CSV file manifest and SHA-256 integrity checks.')}</p></div><div class="dl-repro-grid"><article class="dl-repro-card"><span>DCAT 3</span><h3>${t('Каталог наборов и дистрибуций','Dataset and distribution catalog')}</h3><p>${t('Источник представлен как набор данных, а PDF, CSV, XLSX, JSON и производные выгрузки — как отдельные дистрибуции с правами и контрольными суммами.','A source is represented as a dataset, while PDF, CSV, XLSX, JSON and derived exports are separate distributions with rights and checksums.')}</p><a class="dl-btn" href="/api/data-catalog/dcat.jsonld" target="_blank">${icon('code')}JSON-LD</a></article><article class="dl-repro-card"><span>CSVW</span><h3>${t('Описание аналитических таблиц','Analytical table descriptions')}</h3><p>${t('Каждый набор Data Explorer публикует названия, типы и смысл колонок независимо от конкретной визуализации.','Every Data Explorer dataset publishes column names, data types and semantics independently of any visualisation.')}</p><a class="dl-btn" href="/api/data-explorer/datasets/index_scores/metadata.json" target="_blank">${icon('code')}Metadata</a></article><article class="dl-repro-card"><span>SHA-256</span><h3>${t('Контроль целостности','Integrity control')}</h3><p>${t(`${fmt(s.registered_snapshots,0)} snapshots и ${fmt(s.reproducibility_artifacts,0)} артефактов связаны с контрольными суммами.`,`${fmt(s.registered_snapshots,0)} snapshots and ${fmt(s.reproducibility_artifacts,0)} artifacts are linked to checksums.`)}</p><a class="dl-btn" href="/api/data-catalog/manifest.csv">${icon('download')}${t('CSV-манифест','CSV manifest')}</a></article></div><div class="dl-section" style="padding-top:52px"><div class="dl-section-head"><div><p class="dl-kicker">RIGHTS-AWARE ACCESS</p><h2>${t('Открытость без нарушения условий источника','Openness without violating source terms')}</h2></div></div><div class="dl-rights-grid"><article><b>01</b><h3>${t('Исходник разрешён','Raw approved')}</h3><p>${t('Файл можно просмотреть и скачать; интерфейс показывает атрибуцию, официальный URL и SHA-256.','The file can be previewed and downloaded; attribution, official URL and SHA-256 are shown.')}</p></article><article><b>02</b><h3>${t('Raw не распространяется','Raw not redistributed')}</h3><p>${t('Сохраняются метаданные, официальный адрес, хеш, recipe и разрешённая производная выгрузка.','Metadata, official address, checksum, recipe and an approved derived export are retained.')}</p></article><article><b>03</b><h3>${t('Условия неясны','Terms uncertain')}</h3><p>${t('Применяется консервативный режим: публичны только метаданные и ссылка на правообладателя до дополнительной проверки.','A conservative mode applies: only metadata and the publisher link are public until further review.')}</p></article></div></div><div class="dl-section"><div class="dl-section-head"><div><p class="dl-kicker">${t('Масштаб базы','Database scope')}</p><h2>${t('Из каких аналитических слоёв состоит база','Analytical layers in the database')}</h2></div></div><div class="dl-db-grid">${Object.entries(s.database_rows||{}).map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><strong>${fmt(v,0)}</strong></div>`).join('')}</div></div></section>`}

  function render(){const app=$('#dl-app');app.className='dl-page';app.innerHTML=hero()+mobileTabs()+`<div class="dl-content">${overview()}${explorer()}${sourcesPanel()}${filesPanel()}${reproPanel()}</div>`;bind();switchTab(state.tab,false)}
  function switchTab(id,scroll=true){state.tab=id;$$('[data-tab]').forEach(b=>b.setAttribute('aria-current',b.dataset.tab===id?'page':'false'));$$('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==id);setURL();if(id==='sources')renderSources();if(id==='files'){if(!state.files.payload)loadFiles();else renderFiles();}if(id==='explorer'&&!state.explorer.result)runExplorer();if(scroll)$(`[data-panel="${id}"]`)?.scrollIntoView({behavior:'smooth',block:'start'})}
  function bind(){$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.go)));$$('[data-source]').forEach(b=>b.addEventListener('click',()=>openSource(b.dataset.source,b)));bindExplorerControls();bindExplorerResult();$('[data-source-q]')?.addEventListener('input',e=>{state.sourceFilters.q=e.target.value;renderSources()});$('[data-source-role]')?.addEventListener('change',e=>{state.sourceFilters.role=e.target.value;renderSources()});$('[data-source-access]')?.addEventListener('change',e=>{state.sourceFilters.access=e.target.value;renderSources()});let timer;$('[data-file-q]')?.addEventListener('input',e=>{clearTimeout(timer);state.files.q=e.target.value;state.files.page=1;timer=setTimeout(loadFiles,250)});$('[data-file-source]')?.addEventListener('change',e=>{state.files.source=e.target.value;state.files.page=1;loadFiles()});$('[data-file-ext]')?.addEventListener('change',e=>{state.files.extension=e.target.value;state.files.page=1;loadFiles()});$('[data-file-access]')?.addEventListener('change',e=>{state.files.access=e.target.value;state.files.page=1;loadFiles()});renderSources()}
  function bindExplorerControls(){$('[data-ex-dataset]')?.addEventListener('change',e=>{state.explorer.dataset=e.target.value;initExplorer(true);const panel=$('[data-panel="explorer"]');panel.outerHTML=explorer();bindExplorerControls();bindExplorerResult();runExplorer()});$('[data-ex-measure]')?.addEventListener('change',e=>{state.explorer.measure=e.target.value;runExplorer()});$$('[data-ex-chart]').forEach(b=>b.addEventListener('click',()=>{state.explorer.chart=b.dataset.exChart;const aside=$('.dl-explorer-controls');aside.innerHTML=explorerControls(dataset());bindExplorerControls();runExplorer()}));$$('[data-dim]').forEach(s=>s.addEventListener('change',e=>{state.explorer.dims[e.target.dataset.dim]=e.target.value;runExplorer()}));$('[data-ex-year-from]')?.addEventListener('change',e=>{state.explorer.yearFrom=e.target.value;runExplorer()});$('[data-ex-year-to]')?.addEventListener('change',e=>{state.explorer.yearTo=e.target.value;runExplorer()});$('[data-x-measure]')?.addEventListener('change',e=>{state.explorer.xMeasure=e.target.value;runExplorer()});$('[data-scatter-x]')?.addEventListener('change',e=>{state.explorer.scatterX=e.target.value;runExplorer()});$('[data-scatter-y]')?.addEventListener('change',e=>{state.explorer.scatterY=e.target.value;runExplorer()});$$('[data-run-explorer]').forEach(b=>b.addEventListener('click',runExplorer));$('[data-country-button]')?.addEventListener('click',e=>{const p=$('.dl-country-popover');const open=p.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});$('[data-country-search]')?.addEventListener('input',e=>{const list=$('.dl-country-list');list.innerHTML=countryOptions(e.target.value);bindCountryChecks()});bindCountryChecks();const presets={tech:['RUS','CHN','USA','DEU','KOR','SGP'],brics:['RUS','BRA','IND','CHN','ZAF'],g20:['RUS','ARG','AUS','BRA','CAN','CHN','FRA','DEU','IND','IDN','ITA','JPN']};$$('[data-preset]').forEach(b=>b.addEventListener('click',()=>{state.explorer.countries=new Set((presets[b.dataset.preset]||[]).filter(iso=>state.schema.countries.some(c=>c.iso3===iso)));refreshExplorerControls();runExplorer()}));$('[data-clear-countries]')?.addEventListener('click',()=>{state.explorer.countries.clear();refreshExplorerControls();runExplorer()});$$('[data-remove-country]').forEach(b=>b.addEventListener('click',()=>{state.explorer.countries.delete(b.dataset.removeCountry);refreshExplorerControls();runExplorer()}))}
  function bindCountryChecks(){$$('[data-country-check]').forEach(box=>box.addEventListener('change',e=>{const iso=e.target.value;if(e.target.checked){if(state.explorer.countries.size>=12){e.target.checked=false;toast(t('Можно выбрать не более 12 стран','Up to 12 countries can be selected'));return}state.explorer.countries.add(iso)}else state.explorer.countries.delete(iso);refreshExplorerControls(false)}))}
  function refreshExplorerControls(rebind=true){const aside=$('.dl-explorer-controls');if(!aside)return;aside.innerHTML=explorerControls(dataset());if(rebind)bindExplorerControls();setURL()}
  function bindExplorerResult(){$('[data-copy-link]')?.addEventListener('click',async()=>{setURL();try{await navigator.clipboard.writeText(location.href);toast(t('Ссылка на выборку скопирована','Selection link copied'))}catch{toast(location.href)}});$$('[data-provenance]').forEach(b=>b.addEventListener('click',()=>openProvenance(b.dataset.provenance,b)));bindTips()}
  function bindTips(){const tt=$('#dl-tooltip');$$('[data-tip]').forEach(el=>{const show=e=>{tt.innerHTML=esc(el.dataset.tip).replace(/\n/g,'<br>');tt.style.display='block';const rect=el.getBoundingClientRect(),x=(e.clientX||rect.left)+12,y=(e.clientY||rect.top)+12;requestAnimationFrame(()=>{tt.style.left=`${Math.min(innerWidth-tt.offsetWidth-12,x)}px`;tt.style.top=`${Math.min(innerHeight-tt.offsetHeight-12,y)}px`})};el.addEventListener('mousemove',show);el.addEventListener('focus',show);el.addEventListener('mouseleave',()=>tt.style.display='none');el.addEventListener('blur',()=>tt.style.display='none')})}

  function dialogOpen(kicker,title,subtitle,body,trigger){state.lastFocus=trigger||document.activeElement;$('#dl-dialog-kicker').textContent=kicker;$('#dl-dialog-title').textContent=title;$('#dl-dialog-subtitle').textContent=subtitle||'';$('#dl-dialog-body').innerHTML=body;const d=$('#dl-dialog');if(!d.open)d.showModal();setTimeout(()=>$('#dl-dialog-close').focus(),0)}
  function dialogSet(kicker,title,subtitle,body){$('#dl-dialog-kicker').textContent=kicker;$('#dl-dialog-title').textContent=title;$('#dl-dialog-subtitle').textContent=subtitle||'';$('#dl-dialog-body').innerHTML=body;bindDialogContent()}
  function dialogClose(){const d=$('#dl-dialog');if(d.open)d.close();state.lastFocus?.focus?.()}
  function detailRow(label,value,html=false){return `<div class="dl-detail-row"><span>${esc(label)}</span><strong>${html?value:esc(value??'—')}</strong></div>`}
  async function openSource(id,trigger){dialogOpen(t('Источник данных','Data source'),id,t('Загрузка метаданных…','Loading metadata…'),'<div class="dl-loading compact"><div><div class="dl-loading-mark">G</div></div></div>',trigger);try{const s=await api(`/api/data-catalog/sources/${encodeURIComponent(id)}`);const restricted=!s.redistribution_allowed&&!s.downloadable_count;const body=`<div class="dl-dialog-grid"><section class="dl-dialog-card"><h3>${t('Паспорт источника','Source record')}</h3><div class="dl-detail-list">${detailRow(t('Организация','Publisher'),s.owner)}${detailRow(t('Роль в платформе','Platform role'),String(s.source_role||'').replaceAll('_',' '))}${detailRow(t('Временной охват','Temporal coverage'),s.year_min?`${s.year_min}–${s.year_max}`:'—')}${detailRow(t('Стран','Countries'),fmt(s.country_count,0))}${detailRow(t('Наблюдений','Observations'),fmt(s.observation_count,0))}${detailRow(t('Связанные модули','Related modules'),(s.related_indices||[]).join(', ')||'—')}${detailRow(t('Официальная страница','Official page'),/^https?:/.test(s.source_url||'')?`<a href="${esc(s.source_url)}" target="_blank" rel="noopener">${t('Открыть источник','Open source')} ↗</a>`:s.source_url||'—',true)}</div></section><aside class="dl-dialog-card"><h3>${t('Правовой режим','Rights status')}</h3><div class="dl-license ${restricted?'restricted':''}">${restricted?t('Исходные файлы этого источника не публикуются автоматически. Платформа сохраняет разрешённые производные выгрузки, контрольные суммы и официальный URL.','Raw files from this source are not automatically redistributed. The platform retains approved derived exports, checksums and the official URL.'):t('В каталоге имеются дистрибуции, разрешённые к просмотру или скачиванию после проектной проверки.','The catalog contains distributions approved for preview or download after project review.')}</div><div class="dl-detail-list">${detailRow(t('Решение','Decision'),s.release_archive_decision)}${detailRow(t('Атрибуция','Attribution'),s.attribution_required)}${detailRow(t('Статус проверки','Review status'),s.review_status)}${detailRow(t('Условия','Terms'),/^https?:/.test(s.terms_url||'')?`<a href="${esc(s.terms_url)}" target="_blank">${t('Открыть условия','Open terms')} ↗</a>`:s.terms_url||s.license_or_terms||'—',true)}</div></aside></div><section class="dl-dialog-card" style="margin-top:10px"><h3>${t(`Дистрибуции: ${s.distributions.length}`,`Distributions: ${s.distributions.length}`)}</h3><div class="dl-alt-list">${s.distributions.slice(0,100).map(a=>`<div class="dl-alt"><span><strong>${esc(state.lang==='ru'?a.title_ru:a.title_en)}</strong><br><small>${esc(a.distribution_kind)} · ${esc(String(a.extension||'').toUpperCase())} · ${esc(a.bytes_human)}</small></span><button class="dl-btn" data-dialog-file="${esc(a.file_id)}">${a.preview_allowed?t('Просмотр','Preview'):t('Метаданные','Metadata')}</button></div>`).join('')}</div>${s.distributions.length>100?`<p class="dl-meta">${t('Показаны первые 100 дистрибуций. Полный перечень доступен в библиотеке файлов.','The first 100 distributions are shown. Use the file library for the full list.')}</p>`:''}</section>`;dialogSet(id,s.source_name,s.owner||'',body)}catch(e){dialogSet(id,t('Не удалось открыть источник','Could not open source'),' ',`<div class="dl-error">${esc(e.message)}</div>`)}}
  async function openFile(id,trigger){dialogOpen(t('Файл и метаданные','File and metadata'),id,t('Проверяется режим доступа…','Checking access status…'),'<div class="dl-loading compact"><div><div class="dl-loading-mark">G</div></div></div>',trigger);try{const f=await api(`/api/data-catalog/files/${encodeURIComponent(id)}`);let preview=null,error=null;if(f.preview_allowed){try{preview=await api(`/api/data-catalog/files/${encodeURIComponent(id)}/preview`)}catch(e){error=e}}else{error={message:t('Предпросмотр недоступен по условиям распространения.','Preview is unavailable under the distribution terms.'),body:{detail:{message_ru:'Исходный файл зарегистрирован, но не распространяется публично.',message_en:'The raw file is registered but is not publicly redistributed.'}}}}dialogSet(`${String(f.extension||'').toUpperCase()} · ${f.distribution_kind}`,state.lang==='ru'?f.title_ru:f.title_en,f.filename,fileDetail(f,preview,error))}catch(e){dialogSet(id,t('Не удалось открыть файл','Could not open file'),' ',`<div class="dl-error">${esc(e.message)}</div>`)}}
  function fileDetail(f,p,error){const restricted=!f.download_allowed;let content='';if(p){if(p.preview_type==='pdf')content=`<div class="dl-preview-frame"><iframe title="${esc(f.filename)}" src="${esc(p.inline_url)}"></iframe></div>`;else if(p.preview_type==='table')content=`<div class="dl-preview-table"><table><thead><tr>${p.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${p.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(typeof v==='object'?JSON.stringify(v):v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;else if(p.preview_type==='json')content=`<pre class="dl-preview-json">${esc(JSON.stringify(p.json,null,2))}</pre>`;else content=`<pre class="dl-preview-json">${esc(p.text||'')}</pre>`}else if(error){const d=error.body?.detail||{};content=`<div class="dl-license restricted"><strong>${t('Исходный файл зарегистрирован, но не распространяется публично.','The raw file is registered but is not publicly redistributed.')}</strong><br>${esc((state.lang==='ru'?d.message_ru:d.message_en)||error.message)}</div>`}const actions=[];if(f.download_allowed)actions.push(`<a class="dl-btn dl-btn-primary" href="${esc(f.content_url)}">${icon('download')}${t('Скачать файл','Download file')}</a>`);if(/^https?:/.test(f.official_url||''))actions.push(`<a class="dl-btn" href="${esc(f.official_url)}" target="_blank" rel="noopener">${t('Официальный источник','Official source')} ↗</a>`);return `<div class="dl-dialog-grid"><section class="dl-dialog-card"><h3>${t('Паспорт дистрибуции','Distribution record')}</h3><div class="dl-detail-list">${detailRow(t('Источник','Source'),f.source_id)}${detailRow(t('Тип','Type'),f.distribution_kind)}${detailRow(t('Формат','Format'),f.media_type||f.extension)}${detailRow(t('Размер','Size'),f.bytes_human)}${detailRow(t('Год выпуска','Release year'),f.release_year)}${detailRow(t('Дата получения','Retrieved'),f.retrieved_at)}${detailRow(t('Строк в выгрузке','Rows in export'),f.rows_exported)}${detailRow('SHA-256',`<span class="dl-hash">${esc(f.sha256||'—')}</span>`,true)}</div></section><aside class="dl-dialog-card"><h3>${t('Доступ и атрибуция','Access and attribution')}</h3><div class="dl-license ${restricted?'restricted':''}">${restricted?t('Raw-файл не предоставляется для публичного скачивания. Доказательная запись сохраняет хеш, официальный адрес и связанные разрешённые дистрибуции.','The raw file is not offered for public download. The evidence record retains its checksum, official address and related approved distributions.'):t('Файл разрешён к просмотру и скачиванию в рамках проектной проверки.','The file is approved for preview and download under the project review.')}</div><div class="dl-detail-list">${detailRow(t('Решение','Decision'),f.release_archive_decision)}${detailRow(t('Атрибуция','Attribution'),f.attribution_required)}${detailRow('Snapshot',f.snapshot_id)}${detailRow('Artifact',f.artifact_id)}</div></aside></div><div class="dl-preview-actions">${actions.join('')}</div>${content}${(f.alternatives||[]).length?`<section class="dl-dialog-card" style="margin-top:10px"><h3>${t('Связанные дистрибуции','Related distributions')}</h3><div class="dl-alt-list">${f.alternatives.map(a=>`<div class="dl-alt"><span><strong>${esc(state.lang==='ru'?a.title_ru:a.title_en)}</strong><br><small>${esc(a.distribution_kind)} · ${esc(String(a.extension||'').toUpperCase())} · ${esc(a.bytes_human)}</small></span><button class="dl-btn" data-dialog-file="${esc(a.file_id)}">${t('Открыть','Open')}</button></div>`).join('')}</div></section>`:''}`}
  async function openProvenance(id,trigger){dialogOpen('PROVENANCE',id,t('Загрузка доказательной цепочки…','Loading evidence chain…'),'<div class="dl-loading compact"><div><div class="dl-loading-mark">G</div></div></div>',trigger);try{const p=await api(`/api/data-explorer/provenance/${encodeURIComponent(id)}`);const source=p.source||{},snap=p.snapshot||{};dialogSet('PROVENANCE',id,p.dataset,`<div class="dl-dialog-grid"><section class="dl-dialog-card"><h3>${t('Опубликованное значение','Published value')}</h3><div class="dl-detail-list">${detailRow(t('Таблица','Table'),p.table)}${detailRow(t('Версия формулы','Formula version'),p.formula_version)}${detailRow(t('Преобразование','Transformation'),p.transform_id)}${detailRow(t('Качество','Quality'),p.quality_flag)}</div></section><section class="dl-dialog-card"><h3>${t('Источник и snapshot','Source and snapshot')}</h3><div class="dl-detail-list">${detailRow(t('Источник','Source'),source.source_name||source.source_id)}${detailRow(t('Организация','Publisher'),source.owner)}${detailRow(t('Дата получения','Retrieved'),snap.retrieved_at)}${detailRow(t('Raw snapshot','Raw snapshot'),snap.raw_snapshot_path)}${detailRow('SHA-256',`<span class="dl-hash">${esc(snap.raw_snapshot_sha256||'—')}</span>`,true)}</div></section></div><section class="dl-dialog-card" style="margin-top:10px"><h3>${t('Запись аналитической таблицы','Analytical table record')}</h3><pre class="dl-preview-json">${esc(JSON.stringify(p.record,null,2))}</pre></section>`)}catch(e){dialogSet('PROVENANCE',id,'',`<div class="dl-error">${esc(e.message)}</div>`)}}
  function bindDialogContent(){$$('[data-dialog-file]',$('#dl-dialog')).forEach(b=>b.addEventListener('click',()=>openFile(b.dataset.dialogFile,b)))}

  async function init(){applyStaticI18n();try{const[summary,schema,sourcePayload]=await Promise.all([api('/api/data-catalog/summary'),api('/api/data-explorer/schema'),api('/api/data-catalog/sources')]);state.summary=summary;state.schema=schema;state.sources=sourcePayload.sources||[];if(!state.schema.datasets.length)throw new Error(t('В базе нет таблиц, доступных для Data Explorer','No database tables are available to Data Explorer'));if(!state.schema.datasets.some(d=>d.id===state.explorer.dataset))state.explorer.dataset=state.schema.datasets[0].id;initExplorer(false);render()}catch(e){$('#dl-app').className='dl-error';$('#dl-app').innerHTML=`<h1>${t('Data Lab не загрузился','Data Lab could not load')}</h1><p>${esc(e.message)}</p>`;console.error(e)}}
  $('#dl-theme').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;localStorage.setItem('gir-theme',state.theme)});
  $('#dl-lang').addEventListener('click',()=>{state.lang=state.lang==='ru'?'en':'ru';document.documentElement.lang=state.lang;localStorage.setItem('gir-lang',state.lang);applyStaticI18n();if(state.summary)render()});
  $('#dl-dialog-close').addEventListener('click',dialogClose);$('#dl-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)dialogClose()});$('#dl-dialog').addEventListener('cancel',e=>{e.preventDefault();dialogClose()});document.addEventListener('keydown',e=>{const d=$('#dl-dialog');if(e.key==='Escape'&&d.open){e.preventDefault();dialogClose()}if(e.key==='Tab'&&d.open){const focusable=$$('a[href],button:not([disabled]),input,select,textarea,[tabindex]:not([tabindex="-1"])',d).filter(x=>!x.hidden);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
  document.addEventListener('DOMContentLoaded',init);
})();
